#include "session/SessionOrchestrator.hpp"
#include "core/Saturating.hpp"
namespace elysium::session {bool SessionOrchestrator::predict(SessionCommandIntent i){if(!sessionStableId_||!i.sequence||!i.actorStableId||!i.commandContentId||predictions_.contains(i.sequence))return false;predictions_[i.sequence]={std::move(i),CommandStatus::Predicted,0};return true;}AuthorityResult SessionOrchestrator::authorityProcess(std::uint64_t seq,const std::function<AuthorityCommit(const SessionCommandIntent&)>&fn,elysium::save::SpatialDeltaStore&store){AuthorityResult o;o.sequence=seq;auto i=predictions_.find(seq);if(i==predictions_.end()||i->second.status!=CommandStatus::Predicted||!fn){o.failure=AuthorityFailure::InvalidIntent;return o;}auto c=fn(i->second.intent);if(!c.accepted){i->second.status=CommandStatus::Rejected;o.failure=AuthorityFailure::ValidationRejected;revision_=elysium::safe::saturatingIncrement(revision_);o.revision=revision_;return o;}for(auto d:c.persistentDeltas){if(store.apply(d)!=elysium::save::DeltaCodecFailure::None){i->second.status=CommandStatus::Rejected;o.failure=AuthorityFailure::PersistentWriteRejected;revision_=elysium::safe::saturatingIncrement(revision_);o.revision=revision_;return o;}o.publishedDeltas.push_back(std::move(d));}i->second.status=CommandStatus::Confirmed;i->second.authoritativeRevision=c.newRevision;revision_=elysium::safe::saturatingIncrement(revision_);o.accepted=true;o.revision=revision_;return o;}bool SessionOrchestrator::reject(std::uint64_t seq,AuthorityFailure){auto i=predictions_.find(seq);if(i==predictions_.end()||i->second.status!=CommandStatus::Predicted)return false;i->second.status=CommandStatus::Rejected;revision_=elysium::safe::saturatingIncrement(revision_);return true;}PresentSnapshot SessionOrchestrator::present(std::uint64_t tick)const{PresentSnapshot o{sessionStableId_,tick,revision_,{}};for(auto&[_,p]:predictions_)o.commands.push_back(p);return o;}const PredictionRecord*SessionOrchestrator::prediction(std::uint64_t seq)const{auto i=predictions_.find(seq);return i==predictions_.end()?nullptr:&i->second;}}
